begin;
with source as(select * from jsonb_to_recordset('[{"work": "니지산지", "name": "ChroNoiR", "characters": ["카나에", "쿠즈하"], "kind": "combination", "basis": "니지산지 공식 소개의 두 멤버 유닛 (CP 의미로 추정하지 않음)", "sources": ["https://www.nijisanji.jp/events/chronoir_onemanlive2024/cle-noir/about/"], "verified_on": "2026-11-23"}, {"work": "니지산지", "name": "クロノワール", "characters": ["카나에", "쿠즈하"], "kind": "combination", "basis": "니지산지 공식 소개의 두 멤버 유닛 (CP 의미로 추정하지 않음)", "sources": ["https://www.nijisanji.jp/events/chronoir_onemanlive2024/cle-noir/about/"], "verified_on": "2026-11-23"}, {"work": "니지산지", "name": "くろのわ", "characters": ["카나에", "쿠즈하"], "kind": "combination", "basis": "니지산지 공식 소개의 두 멤버 유닛 (CP 의미로 추정하지 않음)", "sources": ["https://www.nijisanji.jp/events/chronoir_onemanlive2024/cle-noir/about/"], "verified_on": "2026-11-23"}, {"work": "니지산지", "name": "크로노와", "characters": ["카나에", "쿠즈하"], "kind": "combination", "basis": "니지산지 공식 소개의 두 멤버 유닛 (CP 의미로 추정하지 않음)", "sources": ["https://www.nijisanji.jp/events/chronoir_onemanlive2024/cle-noir/about/"], "verified_on": "2026-11-23"}, {"work": "니지산지", "name": "쿠로노와", "characters": ["카나에", "쿠즈하"], "kind": "combination", "basis": "니지산지 공식 소개의 두 멤버 유닛 (CP 의미로 추정하지 않음)", "sources": ["https://www.nijisanji.jp/events/chronoir_onemanlive2024/cle-noir/about/"], "verified_on": "2026-11-23"}]'::jsonb) as x(work text,name text,characters jsonb,kind text,sources jsonb,verified_on date))
insert into public.catalog_cp_aliases(work_key,name,character_names,kind,reference_urls,verified_on) select w.work_key,x.name,array(select jsonb_array_elements_text(x.characters)),x.kind,array(select jsonb_array_elements_text(x.sources)),x.verified_on from source x join public.catalog_works w on w.name=x.work on conflict(work_key,name) do nothing;
notify pgrst,'reload schema';
commit;
